head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf45000";
scwin.fileList = null;
scwin.upd_attachFiles = null;
scwin.upd_attachFiles_2 = null;
scwin.upd_attachFiles_3 = null;
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_bdchrgRegNoFileInstYn", fn: function () { return String(String((dma_pageContext.get("bdchrgRegNoFileInstYn") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name initBdchrgInfo
 * @description init Bdchrg Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.initBdchrgInfo = function () {
    const inputs = document.querySelectorAll("#dtlInfo input[type='text']");
    inputs.forEach(function(input) {
            input.value = "";
    });
    const selects = document.querySelectorAll("#dtlInfo select");
    selects.forEach(function(select) {
            selects.selectedIndex = -1;
    });
    (($c.util.getComponent('ipt_chrgNm')) && ($c.util.getComponent('ipt_chrgNm')).setReadOnly ? ($c.util.getComponent('ipt_chrgNm')).setReadOnly(((true) === '' || (true) === false || (true) === 'false') ? false : (((true) === true || (true) === 'true' || (true) === 'readonly') ? true : (true))) : void 0);
    (($c.util.getComponent('ipt_belngInstNm')) && ($c.util.getComponent('ipt_belngInstNm')).setReadOnly ? ($c.util.getComponent('ipt_belngInstNm')).setReadOnly(((true) === '' || (true) === false || (true) === 'false') ? false : (((true) === true || (true) === 'true' || (true) === 'readonly') ? true : (true))) : void 0);
    $c.util.getComponent('ipt_addNew').setValue("");
};

/**
 * @method
 * @name initFileList
 * @description init File List 처리
 * @returns {void}
 * @hidden N
 */
scwin.initFileList = function () {
    const inputs = document.querySelectorAll("#dtlInfo input[type='text']");
    inputs.forEach(function(input) {
            input.value = "";
    });
    const files = document.querySelectorAll("#dtlInfo input[type='file']");
    files.forEach(function(file) {
            file.value = "";
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.fileList.setStyle("display", "none");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf45000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_SendForm = { action: "", method: 'post', target: '' };

try { scwin.dmenus ={
        "bmenu":7
        ,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf45000' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.fileList = $c.util.getComponent('fileList');
        scwin.upd_attachFiles = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles"]');
        scwin.upd_attachFiles_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_2"]');
        scwin.upd_attachFiles_3 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_3"]');
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf45000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
