 */
scwin.btn_AddNewBdchrg_onclick = async function(e){
    try {
        await scwin.addNewBdchrg()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf45000.btn_AddNewBdchrg_onclick' }); }
};

/**
 * @method
 * @name chgrList_oncellclick
 * @description chgrList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chgrList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: focus_tr (인자 미해석) */

    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'chgrList.oncellclick' });
    }
};

