///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Update
 * @description Update 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Update = async function () {
    const sbmOptions = {
        id: "tx_fn_Update",
        method: "post",
        action: "/register/registerNew.do?method=changeBdchrg",
        ref: "dma_UpdateReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_downloadDoc
 * @description download Doc 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_downloadDoc = async function () {
    try { return await $c.data.downFile("/main/notice.do?method=downloadFile", "", ($c.util.getComponent("dma_downloadDocReq") ? $c.util.getComponent("dma_downloadDocReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fn_SelectBdchrgDtlInfo
 * @description Select Bdchrg Dtl Info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SelectBdchrgDtlInfo = async function () {
    const sbmOptions = {
        id: "tx_fn_SelectBdchrgDtlInfo",
        method: "post",
        action: "/account/userInfo.do?method=selectBdchrgDtlInfo",
        ref: "dma_SelectBdchrgDtlInfoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function () {
    if (!await scwin.chkData()) {
        return false;
    }
    scwin.setCellphoneNoEtc();
    const SendForm = (document.SendForm || { elements: [] });
    if (await $c.win.confirm("변경하시겠습니까?")) {
        const addNew = $c.util.getComponent('ipt_addNew').getValue();
        if (addNew === "ADD") {
            /* 수동 전환 필요: 이름 선택자 순회 [name=doc_bdchrg_tp_cd] — B4 반복 밖 동명 입력(정적/계수 틀) · to-be 에 돌 요소가 없다 */ $("input[name='doc_bdchrg_tp_cd']").each(function(index) {
                    $(this).val($c.util.getComponent('slc_bdchrgTpCd').getValue());
            });
            scwin.form_SendForm.action = "/register/registerNew.do?method=changeBdchrg";
        } else {
            scwin.form_SendForm.action = "/register/registerNew.do?method=updateBdchrgInfo";
        }
        scwin.form_SendForm.target = "_self";
        await scwin.tx_fn_Update();
    }
};

/**
 * @method
 * @name getChrgNm
 * @description get Chrg Nm 처리
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.getChrgNm = function (index) {
    const table = $c.util.getComponent("chgrList");
    const row = table.rows[index];
    let name = "";
    if (row) {
        const rowData = Array.from(row.cells).map(function(cell) {
                return cell.textContent;
        });
        name = rowData[1];
    }
    return name;
};

/**
 * @method
 * @name getSelectedIndex
 * @description get Selected Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.getSelectedIndex = function () {
    const rows = document.querySelectorAll("#chgrList tr");
    let selectedIndex = -1;
    rows.forEach(function(row, index) {
            if (row.classList.contains("on")) {
                selectedIndex = index;
            }
    });
    return selectedIndex;
};

/**
 * @method
 * @name addNewBdchrg
 * @description add New Bdchrg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addNewBdchrg = async function () {
    const selectedIndex = scwin.getSelectedIndex();
    if (selectedIndex < 0) {
        await $c.win.alert("변경 대상 담당자를 선택하세요.");
        return;
    }
    const name = scwin.getChrgNm(selectedIndex);
    const message = "[" + name + "] 을(를) 다른 사람으로 변경하시겠습니까?";
    if (!await $c.win.confirm(message)) {
        return;
    }
    scwin.fileList.setStyle("display", "");
    scwin.initBdchrgInfo();
    scwin.initFileList();
    (($c.util.getComponent('ipt_chrgNm')) && ($c.util.getComponent('ipt_chrgNm')).setReadOnly ? ($c.util.getComponent('ipt_chrgNm')).setReadOnly(((false) === '' || (false) === false || (false) === 'false') ? false : (((false) === true || (false) === 'true' || (false) === 'readonly') ? true : (false))) : void 0);
    (($c.util.getComponent('ipt_belngInstNm')) && ($c.util.getComponent('ipt_belngInstNm')).setReadOnly ? ($c.util.getComponent('ipt_belngInstNm')).setReadOnly(((false) === '' || (false) === false || (false) === 'false') ? false : (((false) === true || (false) === 'true' || (false) === 'readonly') ? true : (false))) : void 0);
    $c.util.getComponent('ipt_addNew').setValue("ADD");
};

/**
 * @method
 * @name fnReset
 * @description fn Reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnReset = function () {
    (document.SendForm || { elements: [] }).reset();
};

/**
 * @method
 * @name focus_tr
 * @description focus tr 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.focus_tr = async function (obj) {
    let i;
    const tabNum = obj.parentNode.children.length;
    for (i = 0; i < tabNum; i++) {
        obj.parentNode.children[i].className = '';
    }
    obj.className = 'on';
    scwin.fileList.setStyle("display", "none");
    scwin.initFileList();
    scwin.initBdchrgInfo();
    await scwin.selectBdchrgDtlInfo(obj.rowIndex - 1, obj.parentNode.children.length);
};

/**
 * @method
 * @name downloadDoc
 * @description download Doc 처리
 * @param {String} docCd docCd
 * @param {String} fileNm fileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.downloadDoc = async function (docCd, fileNm) {
    if (!await $c.win.confirm(fileNm + " 다운로드 하시겠습니까?")) {
        return;
    }
    const fm = (document.fileDownForm || { elements: [] });
    $c.util.getComponent("dma_UpdateReq").set("contnId", docCd);
    fm.action = '/main/notice.do?method=downloadFile';
    await scwin.tx_fn_downloadDoc();
    return;
};

/**
 * @method
 * @name setTelNo
 * @description set Tel No 처리
 * @param {*} pTelNo pTelNo
 * @returns {void}
 * @hidden N
 */
scwin.setTelNo = function (pTelNo) {
    if (pTelNo != null && pTelNo !== '') {
        const pTelNoArr = pTelNo.split('-');
        if (pTelNoArr.length === 3) {
            if (pTelNoArr[0] === "00") {
                $c.util.getComponent('ipt_telNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_telNo1').setValue(pTelNoArr[0]);
            }
            $c.util.getComponent('ipt_telNo2').setValue(pTelNoArr[1]);
            $c.util.getComponent('ipt_telNo3').setValue(pTelNoArr[2]);
        } else {

        }
    }
};

