/**
 * @method
 * @name chkData
 * @description chk Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkData = async function () {
    const SendForm = (document.SendForm || { elements: [] });
    if ($c.util.getComponent('ipt_chrgNm').getValue().trim() === "") {
        await $c.win.alert("이름을 입력하세요.");
        $c.util.getComponent("ipt_chrgNm").focus();
        return false;
    }
    if ($c.util.getComponent('ipt_jobposNm').getValue().trim() === "") {
        await $c.win.alert("직책을 입력하세요.");
        $c.util.getComponent("ipt_jobposNm").focus();
        return false;
    }
    if ($c.util.getComponent('ipt_belngInstNm').getValue().trim() === "") {
        await $c.win.alert("소속기관을 입력하세요.");
        $c.util.getComponent("ipt_belngInstNm").focus();
        return false;
    }
    if ($c.util.getComponent('ipt_belngDepNm').getValue().trim() === "") {
        await $c.win.alert("소속부서를 입력하세요.");
        $c.util.getComponent("ipt_belngDepNm").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_telNo2').getValue() == null ? '' : String($c.util.getComponent('ipt_telNo2').getValue())) === '') {
        await $c.win.alert("전화번호를 입력하세요.");
        $c.util.getComponent("ipt_telNo2").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_telNo3').getValue() == null ? '' : String($c.util.getComponent('ipt_telNo3').getValue())) === '') {
        await $c.win.alert("전화번호를 입력하세요.");
        $c.util.getComponent("ipt_telNo3").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_encrypCellphoneNo1').getValue() == null ? '' : String($c.util.getComponent('ipt_encrypCellphoneNo1').getValue())) === '') {
        await $c.win.alert("휴대전화번호를 입력하세요.");
        $c.util.getComponent("ipt_encrypCellphoneNo1").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_encrypCellphoneNo2').getValue() == null ? '' : String($c.util.getComponent('ipt_encrypCellphoneNo2').getValue())) === '') {
        await $c.win.alert("휴대전화번호를 입력하세요.");
        $c.util.getComponent("ipt_encrypCellphoneNo2").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_encrypCellphoneNo3').getValue() == null ? '' : String($c.util.getComponent('ipt_encrypCellphoneNo3').getValue())) === '') {
        await $c.win.alert("휴대전화번호를 입력하세요.");
        $c.util.getComponent("ipt_encrypCellphoneNo3").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_encrypEmail1').getValue() == null ? '' : String($c.util.getComponent('ipt_encrypEmail1').getValue())) === '') {
        await $c.win.alert("이메일을 입력하세요.");
        $c.util.getComponent("ipt_encrypEmail1").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_encrypEmail2').getValue() == null ? '' : String($c.util.getComponent('ipt_encrypEmail2').getValue())) === '') {
        await $c.win.alert("이메일을 입력하세요.");
        $c.util.getComponent("ipt_encrypEmail2").focus();
        return false;
    }
    const addNew = $c.util.getComponent('ipt_addNew').getValue();
    if (addNew === "ADD") {
        if ($c.util.getComponent("dma_UpdateReq").get("bfBdchrgTpCd") !== $c.util.getComponent('slc_bdchrgTpCd').getValue()) {
            await $c.win.alert("담당자구분은 변경할 수 없습니다.");
            $c.util.getComponent('slc_bdchrgTpCd').setValue(endForm.bf_bdchrg_tp_cd.value);
            return false;
        }
        if ("Y" !== $c.util.getComponent("dma_UpdateReq").get("bdchrgRegNoFileInstYn")) {
            const attach_file = document.getElementsByName("bdchrg_appl_doc_cd");
            for (let i = 0; i < attach_file.length; i++) {
                if ($("input[name='attach_file_nm[" + i + "]']").val() === "") {
                    await $c.win.alert("필수 첨부파일을 입력하세요.");
                    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name setCellphoneNoEtc
 * @description set Cellphone No Etc 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCellphoneNoEtc = function () {
    const SendForm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_telNo1').getValue()) === 0) {
        $c.util.getComponent("ipt_telNo1").setValue("00");
    }
    if (($c.util.getComponent('ipt_faxNo1').getValue() == null ? '' : String($c.util.getComponent('ipt_faxNo1').getValue())) !== '' || ($c.util.getComponent('ipt_faxNo2').getValue() == null ? '' : String($c.util.getComponent('ipt_faxNo2').getValue())) !== '' || ($c.util.getComponent('ipt_faxNo3').getValue() == null ? '' : String($c.util.getComponent('ipt_faxNo3').getValue())) !== '') {
        $c.util.getComponent("dma_UpdateReq").set("faxNo", $c.util.getComponent('ipt_faxNo1').getValue()+ '-' + $c.util.getComponent('ipt_faxNo2').getValue()+ '-' + $c.util.getComponent('ipt_faxNo3').getValue());
    }
    $c.util.getComponent("dma_UpdateReq").set("telNo", $c.util.getComponent('ipt_telNo1').getValue()+ '-' + $c.util.getComponent('ipt_telNo2').getValue()+ '-' + $c.util.getComponent('ipt_telNo3').getValue());
    $c.util.getComponent("dma_UpdateReq").set("encrypEmail", $c.util.getComponent('ipt_encrypEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypEmail2').getValue());
    $c.util.getComponent("dma_UpdateReq").set("encrypCellphoneNo", $c.util.getComponent('ipt_encrypCellphoneNo1').getValue()+ "-" + $c.util.getComponent('ipt_encrypCellphoneNo2').getValue()+ "-" + $c.util.getComponent('ipt_encrypCellphoneNo3').getValue());
};

