// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name selectBdchrgDtlInfoDone
 * @description select Bdchrg Dtl Info Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.selectBdchrgDtlInfoDone = function (data) {
    const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_bfBdchrgTpCd').setValue(result.bdchrg_tp_cd);
    $c.util.getComponent('slc_bdchrgTpCd').setValue(result.bdchrg_tp_cd);
    $c.util.getComponent('ipt_chrgNm').setValue(result.chrg_nm);
    $c.util.getComponent('ipt_jobposNm').setValue(result.jobpos_nm);
    $c.util.getComponent('ipt_belngInstNm').setValue(result.belng_inst_nm);
    $c.util.getComponent('ipt_belngDepNm').setValue(result.belng_dep_nm);
    scwin.setTelNo(result.tel_no);
    scwin.setCellphoneNo(result.cellphone_no);
    scwin.setEmail(result.email);
    scwin.setFaxNo(result.fax_no);
};

/**
 * @method
 * @name selectBdchrgDtlInfo
 * @description select Bdchrg Dtl Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectBdchrgDtlInfo = async function () {
    const r = await scwin.tx_fn_SelectBdchrgDtlInfo();
    try {
        scwin.selectBdchrgDtlInfoDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf45000.fn_SelectBdchrgDtlInfo' });
    }
    return r;
};
